diff --git a/apps/server/src/routes/reports.mjs b/apps/server/src/routes/reports.mjs
--- a/apps/server/src/routes/reports.mjs
+++ b/apps/server/src/routes/reports.mjs
@@ -42,6 +42,14 @@ export function registerReportRoutes({ app, state, requireActor }) {
+  app.get("/api/reports/usage", (req, res) => {
+    const actor = requireActor(req, res);
+    if (!actor) return;
+    const rows = state.invocations.map((inv) => ({
+      id: inv.id, teamId: inv.teamId, agentId: inv.agentId,
+      costUsd: inv.costUsd, createdAt: inv.createdAt,
+    }));
+    res.json({ usage: rows });
+  });
